interface IFileStore {
    IFileInfo fetchInfo();
    String getName();
}
interface IFileInfo {
    boolean isDirectory();
    boolean exists();
}

class DummyFileStore implements IFileStore {
    String name;
    public DummyFileStore(String name) { this.name = name; }
    @Override public IFileInfo fetchInfo() { return null; }
    @Override public String getName() { return name; }
    // Minimal equals/hashCode for correct List behavior
    @Override public int hashCode() { return name.hashCode(); }
    @Override public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;
        DummyFileStore other = (DummyFileStore) obj;
        return name.equals(other.name);
    }
}
class DummyFileInfo implements IFileInfo {
    boolean directory; boolean exists;
    public DummyFileInfo(boolean isDir, boolean exists) { this.directory = isDir; this.exists = exists; }
    @Override public boolean isDirectory() { return directory; }
    @Override public boolean exists() { return exists; }
}

